      pt: { title: "Metafísica", slug: "metafisica", summary: "Ramo da filosofia que investiga a natureza última da realidade: o ser, a substância, a causalidade e as estruturas fundamentais do que existe.", definition: "A metafísica é a investigação filosófica sobre o que existe e sobre as estruturas mais gerais da realidade: ser, substância, identidade, causalidade, tempo, possibilidade e necessidade.", etymology: "Do grego tà metà tà physiká (\"os [livros] depois da Física\"), título dado pelos editores alexandrinos aos tratados de Aristóteles que sucediam à Física. Aristóteles chamava a disciplina de \"filosofia primeira\".", synonyms: ["Filosofia primeira", "Ontologia geral"], nearTerms: ["Ontologia", "Cosmologia", "Teologia natural"], aliases: ["metafisica"] },
      en: { title: "Metaphysics", slug: "metaphysics", summary: "Branch of philosophy investigating the ultimate nature of reality: being, substance, causality and the fundamental structures of what exists.", definition: "Metaphysics is the philosophical inquiry into what exists and into the most general structures of reality: being, substance, identity, causality, time, possibility and necessity.", etymology: "From Greek tà metà tà physiká (\"the [books] after the Physics\"), the title given by Alexandrian editors to Aristotle's treatises following the Physics. Aristotle himself called the discipline \"first philosophy\".", synonyms: ["First philosophy", "General ontology"], nearTerms: ["Ontology", "Cosmology", "Natural theology"] },
      fr: { title: "Métaphysique", slug: "metaphysique", summary: "Branche de la philosophie qui étudie la nature ultime de la réalité : l'être, la substance, la causalité et les structures fondamentales de ce qui existe.", definition: "La métaphysique est l'enquête philosophique sur ce qui existe et sur les structures les plus générales de la réalité.", synonyms: ["Philosophie première"], nearTerms: ["Ontologie"] },
      de: { title: "Metaphysik", slug: "metaphysik", summary: "Zweig der Philosophie, der das letzte Wesen der Wirklichkeit untersucht: Sein, Substanz, Kausalität und die Grundstrukturen des Existierenden.", definition: "Die Metaphysik ist die philosophische Untersuchung dessen, was existiert, und der allgemeinsten Strukturen der Wirklichkeit.", synonyms: ["Erste Philosophie"], nearTerms: ["Ontologie"] },
