      pt: { title: "Ontologia", slug: "ontologia", summary: "Estudo do ser enquanto ser: o que existe e quais são as categorias fundamentais do existente.", definition: "A ontologia é a parte da metafísica que estuda o ser enquanto ser, isto é, as categorias e os modos mais gerais de existir.", etymology: "Do grego ón, óntos (\"ser\", \"ente\") e lógos (\"discurso\", \"estudo\"). O termo foi cunhado no século XVII (Goclenius, 1613).", synonyms: ["Teoria do ser"], nearTerms: ["Metafísica", "Ser", "Ente"] },
      en: { title: "Ontology", slug: "ontology", summary: "The study of being as being: what exists and what the fundamental categories of the existent are.", definition: "Ontology is the part of metaphysics that studies being as being, that is, the most general categories and modes of existing.", etymology: "From Greek ón, óntos (\"being\", \"entity\") and lógos (\"discourse\", \"study\"). The term was coined in the 17th century (Goclenius, 1613).", synonyms: ["Theory of being"], nearTerms: ["Metaphysics", "Being", "Entity"] },
      fr: { title: "Ontologie", slug: "ontologie", summary: "Étude de l'être en tant qu'être : ce qui existe et quelles sont les catégories fondamentales de l'existant.", definition: "L'ontologie est la partie de la métaphysique qui étudie l'être en tant qu'être." },
