      en: { title: "Belief", slug: "belief", summary: "The attitude of taking a proposition to be true; a necessary but not sufficient condition of knowledge.", definition: "Belief is the mental attitude of accepting a proposition as true. It differs from knowledge in requiring neither truth nor justification, and from faith in implying no religious commitment.", etymology: "From Old English gelēafa (\"trust\", \"faith\"); Latin credentia, from credere (\"to trust\", \"to believe\").", synonyms: ["Opinion", "Doxa"], nearTerms: ["Knowledge", "Justification", "Faith", "Doubt"] },
