      en: { title: "Justification", slug: "justification", summary: "The reasons or evidence that make a belief rationally acceptable.", definition: "Epistemic justification is the set of reasons, evidence or reliable processes that support a belief and distinguish it from a lucky guess.", etymology: "From Latin iustificatio, from iustus (\"just\") + facere (\"to make\").", synonyms: ["Warrant", "Grounding"], nearTerms: ["Evidence", "Reason", "Belief", "Knowledge"] },
